#!/usr/bin/env bash
# Undo install.sh: put every file from config/ back to stock end-4 and remove the pinned terminal palette.
#   - files that exist upstream are restored (from a leftover <file>.pre-oh-my-hypr backup if one exists,
#     otherwise downloaded from end-4/dots-hyprland at the commit this repo targets)
#   - files that only this repo adds are deleted, and directories left empty by that are removed
#   - the terminal palette is regenerated by end-4 from the current wallpaper colors
# Idempotent. Use --dry-run to print what would change without touching anything.
set -euo pipefail
UPSTREAM_REF=2f2a376
RAW="https://raw.githubusercontent.com/end-4/dots-hyprland/$UPSTREAM_REF/dots/.config"
ROOT="$(cd "$(dirname "$0")" && pwd)"
DST="${XDG_CONFIG_HOME:-$HOME/.config}"
TDST="${XDG_STATE_HOME:-$HOME/.local/state}/quickshell/user/generated/terminal"
DRY=0
[ "${1:-}" = "--dry-run" ] && DRY=1
CHANGED=0
FAILED=0
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

act() { # act "message" cmd...
  local msg="$1"; shift
  echo "$msg"
  CHANGED=1
  [ "$DRY" = 1 ] || "$@"
}

prune_dirs() { # remove empty parent directories of $1, stopping at $DST
  local d
  d="$(dirname "$1")"
  while [ "$d" != "$DST" ] && [ "$d" != "/" ] && [ -d "$d" ] && [ -z "$(ls -A "$d")" ]; do
    [ "$DRY" = 1 ] || rmdir "$d"
    d="$(dirname "$d")"
  done
}

cd "$ROOT/config"
while read -r f; do
  f="${f#./}"
  t="$DST/$f"
  if [ -e "$t.pre-oh-my-hypr" ]; then
    act "restored $f (from backup)" mv -f "$t.pre-oh-my-hypr" "$t"
    continue
  fi
  [ -e "$t" ] || continue
  code="$(curl -sS -o "$TMP/up" -w '%{http_code}' "$RAW/$f" || echo 000)"
  case "$code" in
    200)
      if cmp -s "$TMP/up" "$t"; then continue; fi
      chmod --reference="$t" "$TMP/up"
      act "restored $f (upstream $UPSTREAM_REF)" cp -p "$TMP/up" "$t"
      ;;
    404)
      act "removed $f" rm -f "$t"
      prune_dirs "$t"
      ;;
    *)
      echo "ERROR: could not fetch upstream $f (HTTP $code); left unchanged" >&2
      FAILED=1
      ;;
  esac
done < <(find . -type f | sort)

# Terminal palette: drop the pinned files, then let end-4 regenerate its own.
for f in kitty-theme.conf sequences.txt; do
  for p in "$TDST/$f" "$TDST/$f.pre-oh-my-hypr"; do
    [ -e "$p" ] && act "removed terminal palette ${p#"$TDST"/}" rm -f "$p"
  done
done
APPLY="$DST/quickshell/ii/scripts/colors/applycolor.sh"
if [ "$DRY" = 0 ] && [ -x "$APPLY" ] && [ -f "${XDG_STATE_HOME:-$HOME/.local/state}/quickshell/user/generated/material_colors.scss" ]; then
  "$APPLY" >/dev/null 2>&1 && echo "regenerated terminal palette from the current theme" \
    || echo "NOTE: palette regeneration failed; change the wallpaper to regenerate it"
else
  echo "NOTE: change the wallpaper (or re-apply the theme) to regenerate the terminal palette"
fi

if [ "$DRY" = 1 ]; then
  echo "Dry run: nothing was changed."
elif [ "$CHANGED" = 1 ]; then
  if command -v hyprctl >/dev/null && hyprctl reload >/dev/null 2>&1; then
    echo "Reloaded Hyprland."
  else
    echo "NOTE: Hyprland was not reloaded; run 'hyprctl reload' inside your session."
  fi
  echo "Done. Restart quickshell to unload QML changes: killall qs quickshell; qs -c ii &"
else
  echo "Already clean."
fi
exit "$FAILED"
